var t=`0049-svickova-na-smetane`;var n=`world-0049`;var i=`CZ`;var r=`eastern-europe`;var s=4;var o=130;var l={en:`Svíčková na Smetaně`,ua:`Свічкова на сметані`};var c={en:`A classic dish from Czechia, featuring beef chuck, yellow onion, carrot, parsley root. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: яловича лопатка, жовта цибуля, морква, корінь петрушки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Brown the beef with the fat in a heavy casserole. Work in batches to avoid steaming.`,ua:`Підрум’яньте яловичину з жиром у важкій каструлі невеликими партіями, щоб м’ясо не тушкувалося.`,t:[`searing`],m:12,i:[[`beef-chuck`,750,`g`],[`lard`,25,`g`]]},{en:`Sauté onion and root vegetables with butter until lightly golden and fragrant.`,ua:`Пасеруйте цибулю та коренеплоди на маслі до легкої золотистості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,150,`g`],[`carrot`,230,`g`],[`parsley-root`,130,`g`],[`celeriac`,140,`g`],[`unsalted-butter`,40,`g`]]},{en:`Return beef to the pot; add stock, bay leaf and allspice, cover and braise slowly until fork tender.`,ua:`Поверніть м’ясо, додайте бульйон, лавровий лист і духмяний перець та повільно тушкуйте під кришкою до м’якості.`,t:[`braising`],m:100,i:[[`beef-stock`,600,`ml`],[`bay-leaf`,2,`leaf`],[`allspice-berries`,5,`pcs`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Blend the softened vegetables with cream, season the sauce sweet-sour with a little vinegar and sugar, then serve over sliced beef.`,ua:`Перебийте овочі з вершками, збалансуйте кисло-солодкий смак оцтом і цукром; полийте соусом скибочки м’яса.`,t:[`seasoning`,`finishing-with-herbs`],m:6,i:[[`heavy-cream`,220,`ml`],[`apple-cider-vinegar`,15,`ml`],[`white-granulated-sugar`,18,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:n,country:`CZ`,region:r,servings:4,minutes:130,title:l,text:c,steps:g};export{i as country,u as default,n as id,o as minutes,r as region,s as servings,t as slug,g as steps,c as text,l as title};